import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SettingsCommand{CommandLine: "gamerule showcoordinates true", SuppressOutput: true}
GAMERULE = bytes.fromhex("1d67616d6572756c652073686f77636f6f7264696e61746573207472756501")

# generated by gophertunnel b8bd735:
# &packet.SettingsCommand{CommandLine: "", SuppressOutput: false}
EMPTY = bytes.fromhex("0000")

# generated by gophertunnel b8bd735:
# &packet.SettingsCommand{CommandLine: strings.Repeat("a", 200), SuppressOutput: false}
LONG = bytes.fromhex("c801") + bytes.fromhex("61") * 200 + bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.SettingsCommandPacket(command_string="gamerule showcoordinates true", suppress_output=True),
        GAMERULE,
        id="gamerule",
    ),
    pytest.param(
        v2225.SettingsCommandPacket(command_string="", suppress_output=False),
        EMPTY,
        id="empty-command-line-is-a-lone-length-prefix",
    ),
    pytest.param(
        v2225.SettingsCommandPacket(command_string="a" * 200, suppress_output=False),
        LONG,
        id="200-byte-command-line-takes-a-varint-length",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_settings_command_is_packet_140(version):
    assert version.PACKETS[140] is version.SettingsCommandPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_settings_command_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_settings_command_decodes_from_its_golden(packet, golden):
    assert v2225.SettingsCommandPacket.from_bytes(golden) == packet
